  var left: f32 = left_values[i];
  var right: f32 = right_values[i];
  var count: u32 = 0u;
  for (var j = 0u; j < params.length; j += 1u) {
    if (j < i) {
      if (left_values[j] < left) {
        count += 1u;
      } else if (left_values[j] == left) {
        count += 1u;
      }
    }
  }
  value = count;
}

